fn is_sorted(arr: &Vec<i32>) -> bool {
    // Since arr has length > 0, we only need to check consecutive pairs
    // for the nondecreasing property. If for every i, arr[i] <= arr[i+1],
    // then the entire array is nondecreasing.
    for i in 0..arr.len() - 1 {
        if arr[i] > arr[i + 1] {
            return false;
        }
    }
    true
}